import { useState } from "react";
import { Button } from "../../ui/button/index.js";
import { FileDialog } from "../../ui/file-dialog/index.js";
import { longFolder, sampleWorkspace, slowListing, without } from "../fixtures/sample-files.js";
import { SectionPage, Specimen } from "../kit.js";

const noop = () => undefined;
const stream = (text: string) => new Blob([text]).stream();
const WORKSPACE = sampleWorkspace();
const SECOND = sampleWorkspace("archive", "Archive");
const SLOW = slowListing(longFolder(2400, 60), 160);
const NO_LISTING = without(
  sampleWorkspace("link", "Link"),
  "readDirectory",
  "write",
  "applyEdits",
  "thumbnail",
  "rename",
  "delete",
  "createDirectory",
  "watch",
);
const READ_ONLY = without(
  sampleWorkspace("published", "Published"),
  "write",
  "applyEdits",
  "rename",
  "delete",
  "createDirectory",
);
const NO_THUMBNAILS = without(sampleWorkspace("plain", "Plain"), "thumbnail");
const CONFLICTS = sampleWorkspace("team", "Team");

export default function FileDialogSection() {
  const [opened, setOpened] = useState("");
  const [saved, setSaved] = useState("");
  const [open, setOpen] = useState(false);
  const [view, setView] = useState<"list" | "grid">("grid");
  const [aborted, setAborted] = useState(0);
  const [abortable] = useState(() =>
    slowListing(sampleWorkspace("distant", "Distant"), 2000, () =>
      setAborted((count) => count + 1),
    ),
  );
  const [rival, setRival] = useState(true);
  const [compared, setCompared] = useState("");
  const [question, setQuestion] = useState<"changed" | "gone" | null>(null);
  const [answer, setAnswer] = useState("");
  return (
    <SectionPage>
      <Specimen
        title="Open"
        description="Multiple selection with Shift, ⌘/Ctrl and the check marks. A dimmed entry says why it can't be chosen. Right-click or the ⋯ menu renames and deletes."
        layout="stack"
        specimenKey="file-dialog:default:0"
      >
        <FileDialog
          mode="open"
          multiple
          providers={[WORKSPACE]}
          trigger={<Button>Open files</Button>}
          onOpen={async (selection, { signal }) => {
            if (!("provider" in selection)) return;
            await Promise.all(
              selection.files.map((file) =>
                selection.provider.read(
                  file.uri,
                  { offset: 0, length: 16 },
                  { signal, version: file.version },
                ),
              ),
            );
            setOpened(selection.files.map((file) => file.name).join(", "));
          }}
        />
        <p data-testid="file-dialog-opened">{opened || "Nothing opened"}</p>
      </Specimen>

      <Specimen
        title="Thumbnails and a filter"
        description="Controlled open and view. Only pictures can be chosen here; the rest stay listed, dimmed. Thumbnail cells have a fixed size and swap in place."
        layout="stack"
        specimenKey="file-dialog:default:1"
      >
        <Button onClick={() => setOpen(true)}>Choose a picture</Button>
        <FileDialog
          mode="open"
          open={open}
          onOpenChange={setOpen}
          view={view}
          onViewChange={setView}
          accept="image/*"
          title="Choose a picture"
          providers={[WORKSPACE]}
          defaultUri="workspace:///Pictures"
          onOpen={(selection) => setOpened(selection.files[0]?.name ?? "")}
        />
      </Specimen>

      <Specimen
        title="Save"
        description="Choosing a format changes the extension. An existing name asks before replacing, and the host writes in onSave."
        layout="stack"
        specimenKey="file-dialog:default:2"
      >
        <FileDialog
          mode="save"
          defaultName="Quarterly plan.txt"
          formats={[
            { label: "Plain text", extension: ".txt", mime: "text/plain" },
            { label: "Markdown", extension: ".md", mime: "text/markdown" },
          ]}
          providers={[READ_ONLY, WORKSPACE]}
          defaultUri="workspace:///Reports"
          trigger={<Button>Save a copy</Button>}
          onSave={async (target, { signal, setProgress }) => {
            setProgress(0.5);
            const result = await target.provider.write!(target.uri, stream("Plan"), {
              base: target.base,
              signal,
              onProgress: () => setProgress(1),
            });
            if (result.status === "written")
              setSaved(`${result.stat.name}, ${JSON.stringify(target.base)}`);
            return result;
          }}
        />
        <p data-testid="file-dialog-saved">{saved || "Nothing saved"}</p>
      </Specimen>

      <Specimen
        title="A conflict"
        description="A rival write lands first, so onSave returns a conflict. The dialog stays open: Replace, Save a copy, Compare or Cancel."
        layout="stack"
        specimenKey="file-dialog:default:3"
      >
        <FileDialog
          mode="save"
          defaultName="Plan.txt"
          providers={[CONFLICTS]}
          trigger={<Button>Save over a rival</Button>}
          onCompare={(current) => setCompared(current?.version ?? "gone")}
          onSave={async (target, { signal }) => {
            if (rival) {
              setRival(false);
              await CONFLICTS.write(target.uri, stream("A rival's version"), {
                base: { overwrite: true },
                signal,
              });
            }
            const result = await target.provider.write!(target.uri, stream("Mine"), {
              base: target.base,
              signal,
            });
            if (result.status === "written")
              setSaved(`${result.stat.name}, ${JSON.stringify(target.base)}`);
            return result;
          }}
        />
        <p data-testid="file-dialog-compared">{compared || "Nothing compared"}</p>
      </Specimen>

      <Specimen
        title="Locations and this device"
        description="Two providers show a location list. device adds FileDrop, which needs no provider and returns File objects."
        layout="stack"
        specimenKey="file-dialog:default:4"
      >
        <FileDialog
          mode="open"
          multiple
          device
          accept=".txt,text/plain"
          providers={[WORKSPACE, SECOND]}
          trigger={<Button>Open from anywhere</Button>}
          onOpen={(selection) => setOpened(selection.files.map((file) => file.name).join(", "))}
        />
      </Specimen>

      <Specimen
        title="A long folder"
        description="2,400 files, 60 at a time, 160 ms a page. Pages join the end, so rows never move. total is known here; the count waits for the last page where it is not."
        layout="stack"
        specimenKey="file-dialog:default:5"
      >
        <FileDialog
          mode="open"
          multiple
          providers={[SLOW]}
          trigger={<Button>Open the long folder</Button>}
          onOpen={(selection) => setOpened(`${selection.files.length} files`)}
        />
      </Specimen>

      <Specimen
        title="Leaving a folder aborts its requests"
        description="Each listing takes two seconds. Going elsewhere before it lands aborts it."
        layout="stack"
        specimenKey="file-dialog:default:6"
      >
        <FileDialog
          mode="open"
          providers={[abortable]}
          trigger={<Button>Open the distant location</Button>}
          onOpen={noop}
        />
        <p data-testid="file-dialog-aborted">{`Listings aborted: ${aborted}`}</p>
      </Specimen>

      <Specimen
        title="What a provider has decides what the dialog offers"
        description="No method, no command. Each button opens a provider that lacks something."
        layout="row"
        specimenKey="file-dialog:default:7"
      >
        <FileDialog
          mode="open"
          providers={[NO_LISTING]}
          trigger={<Button>No readDirectory</Button>}
          onOpen={(selection) => setOpened(selection.files[0]?.name ?? "")}
        />
        <FileDialog
          mode="open"
          providers={[READ_ONLY]}
          trigger={<Button>No write, rename or delete</Button>}
          onOpen={noop}
        />
        <FileDialog
          mode="open"
          defaultView="grid"
          providers={[NO_THUMBNAILS]}
          trigger={<Button>No thumbnail</Button>}
          onOpen={noop}
        />
        <FileDialog
          mode="save"
          defaultName="Notes.txt"
          providers={[READ_ONLY]}
          trigger={<Button>Save with no write</Button>}
          onSave={() => Promise.reject(new Error("Unreachable"))}
        />
      </Specimen>
    </SectionPage>
  );
}
